import System.Exception;import System.ArgumentException;import System.Type;import System.Reflection.MethodInfo;import java.nio.file.*;import java.util.*;
class MethodInfoGenericGuardFailuresProbe {
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static Type[] types(String p){return switch(p){case "null"->null;case "empty"->new Type[0];case "object"->new Type[]{Type.GetType("System.Object")};case "int"->new Type[]{Type.GetType("System.Int32")};case "nullElement"->new Type[]{null};case "objectNull"->new Type[]{Type.GetType("System.Object"),null};case "twoObjects"->new Type[]{Type.GetType("System.Object"),Type.GetType("System.Object")};case "cloneable"->new Type[]{Type.GetType("System.ICloneable")};default->throw new AssertionError(p);};}
 static String outcome(MethodInfo m,String route,String profile){try{if(route.equals("definition"))m.GetGenericMethodDefinition();else m.MakeGenericMethod(types(profile));return "OK";}catch(Exception e){return "ERR|"+e.getClass().getName()+"|"+units(e.get_Message())+"|"+e.get_HResult()+"|"+units(e instanceof ArgumentException a?a.get_ParamName():null);}}
 public static void main(String[] args)throws java.lang.Exception{int cases=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);MethodInfo m=Type.GetType(p[0]).GetMethod(p[1]);if(!m.ToString().equals(p[4]))throw new AssertionError("descriptor "+line);String actual=outcome(m,p[2],p[3]);if(!actual.equals(p[5]))throw new AssertionError("guard "+line+" actual="+actual);cases++;}java.lang.System.out.println("PASS nongeneric MethodInfo guards cases="+cases+" groups="+(cases*2));}
}
